#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    pid_t pid = fork();
    if (pid == 0) {
        printf("Child %d exits now\n", getpid());
        exit(7);
    }
    sleep(10);
    int status;
    pid_t done = wait(&status);
    printf("Parent reaped %d, exit code %d\n", done, WEXITSTATUS(status));
    return 0;
}
